37	/// <summary>
38	/// Loads embedded localization resources and caches the parsed, validated models.
39	/// </summary>
40	/// <remarks>
41	/// Parsing a locale costs an assembly manifest scan, a stream read and a full JSON
42	/// deserialization. Doing that per call made <c>ToWords</c> roughly twenty-five times
43	/// slower than necessary, so every parsed model is cached here for the lifetime of the
44	/// process. The cached instances are never handed out to callers, which is what makes
45	/// sharing them safe.
46	/// </remarks>
47	internal static class LocalizationLoader
48	{
49	    private const string ResourceSuffix = ".json";
50	
51	    private static readonly JsonSerializerOptions SerializerOptions = new()
52	    {
53	        PropertyNameCaseInsensitive = true,
54	        ReadCommentHandling = JsonCommentHandling.Skip,
55	        AllowTrailingCommas = true,
56	    };
57	
58	    private static readonly Lazy<string[]> ResourceNames = new(() =>
59	        typeof(LocalizationLoader).GetTypeInfo().Assembly
60	            .GetManifestResourceNames()
61	            .Where(name => name.EndsWith(ResourceSuffix, StringComparison.OrdinalIgnoreCase))
62	            .OrderBy(name => name, StringComparer.Ordinal)
63	            .ToArray());
64	
65	    private static readonly ConcurrentDictionary<string, LocalizationModel> Cache =
66	        new(StringComparer.Ordinal);
67	
68	    private static readonly Lazy<IReadOnlyList<string>> SupportedCultureNames = new(() =>
69	        ResourceNames.Value
70	            .Select(CultureNameOf)
71	            .Where(culture => !Load(culture).Deprecated)
72	            .OrderBy(culture => culture, StringComparer.Ordinal)
73	            .ToArray());
74	
75	    /// <summary>
76	    /// Gets the culture names shipped with the library, excluding deprecated ones.
77	    /// </summary>
78	    public static IReadOnlyList<string> SupportedCultures => SupportedCultureNames.Value;
