80	    /// <summary>
81	    /// Determines whether a localization resource can be resolved for the given culture.
82	    /// </summary>
83	    public static bool IsSupported(string? culture) =>
84	        !string.IsNullOrWhiteSpace(culture) && TryResolveResourceName(culture!, out _, out _);
85	
86	    /// <summary>
87	    /// Returns the cached, validated localization for the given culture, together with
88	    /// how closely it matched.
89	    /// </summary>
90	    /// <exception cref="ArgumentNullException"><paramref name="culture"/> is <see langword="null"/>.</exception>
91	    /// <exception cref="ArgumentException">The culture is empty or whitespace.</exception>
92	    /// <exception cref="LocalizationNotFoundException">No resource matches the culture.</exception>
93	    /// <exception cref="InvalidLocalizationException">The resource could not be parsed or is invalid.</exception>
94	    public static ResolvedLocalization Resolve(string culture)
95	    {
96	        if (culture is null)
97	            throw new ArgumentNullException(nameof(culture));
98	
99	        if (string.IsNullOrWhiteSpace(culture))
100	        {
101	            throw new ArgumentException(
102	                "Culture must be a non-empty culture name such as \"en-US\". " +
103	                "CultureInfo.InvariantCulture has an empty name and cannot be used; " +
104	                $"supported cultures are: {string.Join(", ", SupportedCultures)}.",
105	                nameof(culture));
106	        }
107	
108	        if (!TryResolveResourceName(culture, out var resourceName, out var regionMatches))
109	            throw new LocalizationNotFoundException(culture, SupportedCultures);
110	
111	        return new ResolvedLocalization(
112	            Cache.GetOrAdd(resourceName, Parse),
113	            CultureNameOf(resourceName),
114	            regionMatches);
115	    }
