117	    private static LocalizationModel Load(string culture) =>
118	        Cache.GetOrAdd(culture + ResourceSuffix, Parse);
119	
120	    private static string CultureNameOf(string resourceName) =>
121	        resourceName.Substring(0, resourceName.Length - ResourceSuffix.Length);
122	
123	    /// <summary>
124	    /// Resolves a culture name to an embedded resource name. Matching is case-insensitive
125	    /// and falls back from a specific culture to another variant of the same language, so
126	    /// <c>"EN-US"</c>, <c>"en"</c> and <c>"en-GB"</c> all resolve to <c>en-US.json</c>.
127	    /// </summary>
128	    /// <remarks>
129	    /// Deprecated localizations resolve only on an exact name, so a redundant file such as
130	    /// <c>tr-TR-EUR</c> can never be picked up by a language fallback.
131	    /// </remarks>
132	    private static bool TryResolveResourceName(string culture, out string resourceName, out bool regionMatches)
133	    {
134	        var names = ResourceNames.Value;
135	
136	        var exact = culture + ResourceSuffix;
137	        foreach (var name in names)
138	        {
139	            if (string.Equals(name, exact, StringComparison.OrdinalIgnoreCase))
140	            {
141	                resourceName = name;
142	                regionMatches = true;
143	                return true;
144	            }
145	        }
146	
147	        var requestedLanguage = LanguageOf(culture);
148	        var requestedRegion = RegionOf(culture);
149	
150	        // Prefer a locale whose region also matches, then the canonical variant of the
151	        // language. Ordering by culture name keeps the choice deterministic; region
152	        // matching keeps it correct when a language ships more than one region.
153	        string? languageMatch = null;
154	
155	        foreach (var name in names)
156	        {
157	            var candidate = CultureNameOf(name);
158	
159	            if (!string.Equals(LanguageOf(candidate), requestedLanguage, StringComparison.OrdinalIgnoreCase))
160	                continue;
161	
162	            if (Load(candidate).Deprecated)
163	                continue;
164	
165	            if (requestedRegion is not null &&
166	                string.Equals(RegionOf(candidate), requestedRegion, StringComparison.OrdinalIgnoreCase))
167	            {
168	                resourceName = name;
169	                regionMatches = true;
170	                return true;
171	            }
172	
173	            languageMatch ??= name;
174	        }
175	
176	        if (languageMatch is not null)
177	        {
178	            resourceName = languageMatch;
179	            // A request that named no region accepts whatever the language's default is;
180	            // a request that named a different region does not, at least for currency.
181	            regionMatches = requestedRegion is null;
182	            return true;
183	        }
184	
185	        resourceName = string.Empty;
186	        regionMatches = false;
187	        return false;
188	    }
189	
190	    private static string LanguageOf(string culture)
191	    {
192	        var separatorIndex = culture.IndexOf("-", StringComparison.Ordinal);
193	        return separatorIndex < 0 ? culture : culture.Substring(0, separatorIndex);
194	    }
195	
196	    private static string? RegionOf(string culture)
197	    {
198	        var parts = culture.Split('-');
199	        return parts.Length < 2 || parts[1].Length == 0 ? null : parts[1];
200	    }
201	
202	    private static LocalizationModel Parse(string resourceName)
203	    {
204	        var assembly = typeof(LocalizationLoader).GetTypeInfo().Assembly;
205	
206	        string json;
207	        using (var stream = assembly.GetManifestResourceStream(resourceName))
208	        {
209	            if (stream is null)
210	            {
211	                throw new InvalidLocalizationException(
212	                    $"The embedded resource '{resourceName}' could not be opened.");
213	            }
214	
215	            using var reader = new StreamReader(stream, Encoding.UTF8);
216	            json = reader.ReadToEnd();
217	        }
218	
219	        LocalizationModel? model;
220	        try
221	        {
222	            model = JsonSerializer.Deserialize<LocalizationModel>(json, SerializerOptions);
223	        }
224	        catch (JsonException ex)
225	        {
226	            throw new InvalidLocalizationException(
227	                $"The embedded resource '{resourceName}' is not valid JSON: {ex.Message}", ex);
228	        }
229	
230	        if (model is null)
231	        {
232	            throw new InvalidLocalizationException(
233	                $"The embedded resource '{resourceName}' deserialized to null.");
234	        }
235	
236	        LocalizationValidator.Validate(model, resourceName);
237	        return model;
238	    }
239	}
