/// <see cref="WordifyOptions.CurrencyCode"/>.</exception>
public NumberToWordsConverter(WordifyOptions options)
    : this(ResolveOptions(options), RequestedCultureOf(options))
{
    // Honouring Currency but silently dropping CurrencyCode would make the same
    // mistake an error on one path and invisible on the other.
    _overriddenCurrency =
        options.Currency is { } currency ? ValidatedOverride(currency)
        : options.CurrencyCode is { } currencyCode
            ? ResolveCurrencyCode(_localization, _resolvedCulture, currencyCode)
            : null;
}

private static ResolvedLocalization ResolveOptions(WordifyOptions options)
{
    if (options is null)
        throw new ArgumentNullException(nameof(options));

    return options.Localization is { } localization
        ? ValidatedCustom(localization)
        : LocalizationLoader.Resolve(options.Culture);
}

private static string RequestedCultureOf(WordifyOptions options) =>
    options.Localization is null ? options.Culture : CustomLocalizationSource;

public static bool IsSupported(string? culture) =>
    !string.IsNullOrWhiteSpace(culture) && TryResolveResourceName(culture!, out _, out _);

/// <summary>
/// Determines whether a localization resource can be resolved for the given culture,
/// and whether that resource's default currency applies to it.
/// </summary>
/// <remarks>
/// Resolving and converting-with-currency are two different questions: a culture that
/// matched only by language keeps the number words but loses the claim to the locale's
/// currency, and a locale is free to define none at all.
/// </remarks>
public static bool IsSupported(string? culture, out bool currencyApplies)
{
    currencyApplies = false;

    if (string.IsNullOrWhiteSpace(culture) ||
        !TryResolveResourceName(culture!, out var resourceName, out var regionMatches))
    {
        return false;
    }

    currencyApplies = regionMatches && Cache.GetOrAdd(resourceName, Parse).DefaultCurrency is not null;
    return true;
}

